$('save').onclick=async()=>{if(busy)return;const button=$('save');button.disabled=true;try{await document.fonts.ready;const poster=renderPoster();const blob=await new Promise(resolve=>poster.toBlob(resolve,'image/png'));if(!blob)throw new Error('图片生成失败，请重试');if(downloadURL)URL.revokeObjectURL(downloadURL);downloadURL=URL.createObjectURL(blob);$('saved-image').src=downloadURL;$('download-link').href=downloadURL;$('download-link').download='Play-the-City.png';$('save-dialog').showModal();if(matchMedia('(pointer:fine)').matches){$('download-link').click();$('save-dialog').querySelector('p').textContent='图片已生成，可预览或再次下载'}else $('save-dialog').querySelector('p').textContent='长按图片保存'}catch(e){notify(e.message)}finally{button.disabled=false}};
